<?php
require_once __DIR__.'/includes/config.php'; require_once __DIR__.'/includes/auth.php'; sisatRequireRoles([1]);
$id=(int)($_GET['id']??$_POST['id']??0);$q=$dbh->prepare('SELECT * FROM usuarios_sistema WHERE id=?');$q->execute([$id]);$u=$q->fetch(PDO::FETCH_ASSOC);if(!$u){http_response_code(404);exit('Usuario no encontrado.');}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$nombre=trim($_POST['nombre_completo']??'');$usuario=trim($_POST['usuario']??'');$correo=trim($_POST['correo']??'');$rol=(int)($_POST['rol_id']??0);if($id===(int)$_SESSION['uid']){$rol=(int)$u['rol_id'];$_POST['estado']=$u['estado'];}$estado=$_POST['estado']??'ACTIVO';$clave=(string)($_POST['clave']??'');if($nombre===''||$usuario===''||!in_array($rol,[1,2,3],true)||!in_array($estado,['ACTIVO','INACTIVO'],true))$error='Verifica los campos obligatorios.';elseif($correo!==''&&!filter_var($correo,FILTER_VALIDATE_EMAIL))$error='Correo no válido.';else{try{$sql='UPDATE usuarios_sistema SET rol_id=?,nombre_completo=?,usuario=?,correo=?,estado=?,fecha_actualizacion=NOW()'.($clave!==''?',password_hash=?':'').' WHERE id=?';$args=[$rol,$nombre,$usuario,$correo?:null,$estado];if($clave!==''){if(strlen($clave)<8)throw new RuntimeException('La clave debe tener mínimo 8 caracteres.');$args[]=password_hash($clave,PASSWORD_DEFAULT);}$args[]=$id;$dbh->prepare($sql)->execute($args);header('Location: manage-usuarios.php');exit;}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'No se pudo actualizar (posible usuario duplicado).';}}}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}include __DIR__.'/includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include __DIR__.'/includes/leftbar.php';?><div class="main-page"><div class="container-fluid"><h2>Actualizar usuario</h2></div><section class="section"><div class="container-fluid"><div class="panel"><div class="panel-body"><?php if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="id" value="<?=$id?>"><div class="form-group"><label>Nombre completo</label><input class="form-control" name="nombre_completo" value="<?=h($u['nombre_completo'])?>" required></div><div class="form-group"><label>Usuario</label><input class="form-control" name="usuario" value="<?=h($u['usuario'])?>" required></div><div class="form-group"><label>Correo</label><input class="form-control" type="email" name="correo" value="<?=h($u['correo'])?>"></div><div class="form-group"><label>Perfil</label><select class="form-control" name="rol_id"><?php foreach([1=>'Administrador',2=>'Técnico',3=>'Gerencia / Consulta'] as $k=>$v):?><option value="<?=$k?>" <?=$u['rol_id']==$k?'selected':''?>><?=h($v)?></option><?php endforeach;?></select></div><div class="form-group"><label>Estado</label><select class="form-control" name="estado"><option <?=$u['estado']==='ACTIVO'?'selected':''?>>ACTIVO</option><option <?=$u['estado']==='INACTIVO'?'selected':''?>>INACTIVO</option></select></div><div class="form-group"><label>Nueva clave (dejar vacía para conservarla)</label><input class="form-control" type="password" name="clave" minlength="8"></div><button class="btn btn-primary">Guardar cambios</button> <a class="btn btn-default" href="manage-usuarios.php">Cancelar</a></form></div></div></div></section></div></div></div><?php include __DIR__.'/includes/footer.php';?>
